import { emit } from './events';
import { schedule } from './scheduler';
const browserHistory = window.history;
let currentPath = '';
let patchedHistory = false;

export function getRoute() {
    const path = window.location.pathname || '';
    const hash = window.location.hash || '';
    const full = `${path}${hash}`;

    return {
        path,
        hash,
        full,

        isLogin: hash.includes('/login') || path.includes('/login'),
        isHome: hash === '#/home.html' || hash === '#/home' || hash.includes('/home'),
        isDashboard: hash.includes('/dashboard') || path.includes('/dashboard'),
        isSettings: hash.includes('/settings') || path.includes('/settings') || hash.includes('/mypreferences'),
        isDetails: hash.includes('/details') || hash.includes('/item'),
        isPlayback: document.documentElement.classList.contains('ptv-playing')
    };
}

function applyRouteClasses(route) {
    const root = document.documentElement;

    root.classList.toggle('ptv-route-login', route.isLogin);
    root.classList.toggle('ptv-route-home', route.isHome);
    root.classList.toggle('ptv-route-dashboard', route.isDashboard);
    root.classList.toggle('ptv-route-settings', route.isSettings);
    root.classList.toggle('ptv-route-details', route.isDetails);
    root.classList.toggle('ptv-route-playback', route.isPlayback);
}

export function checkRoute() {
    const route = getRoute();

    if (route.full === currentPath) {
        return route;
    }

    currentPath = route.full;
    applyRouteClasses(route);
    emit('routechange', route);

    return route;
}

export function scheduleRouteCheck() {
    schedule('route-check', checkRoute);
}

function patchHistory() {
    if (patchedHistory) return;

    patchedHistory = true;

    const originalPushState = browserHistory.pushState;
    const originalReplaceState = browserHistory.replaceState;

    browserHistory.pushState = function (...args) {
        const result = originalPushState.apply(this, args);
        scheduleRouteCheck();
        return result;
    };

    browserHistory.replaceState = function (...args) {
        const result = originalReplaceState.apply(this, args);
        scheduleRouteCheck();
        return result;
    };
}

export function startRouter() {
    patchHistory();

    window.addEventListener('hashchange', scheduleRouteCheck);
    window.addEventListener('popstate', scheduleRouteCheck);

    currentPath = '';
    checkRoute();
}

startRouter();
